// Format the successful OpenRouter response into CreatorOS contract
const openRouterResponse = $input.first().json;
const requestBody = $items('Webhook')[0].json.body;

// Extract the actual model OpenRouter used (from its response, not the request)
const actualModel = openRouterResponse.model || requestBody.payload.model;
const actualProvider = 'openrouter';

// Extract text from the first choice
const text = openRouterResponse.choices?.[0]?.message?.content || '';

// Extract token counts if OpenRouter provided them
const inputTokens = openRouterResponse.usage?.prompt_tokens || 0;
const outputTokens = openRouterResponse.usage?.completion_tokens || 0;

// Build the CreatorOS standard response contract
const response = {
  success: true,
  requestId: requestBody.requestId,
  data: {
    text: text,
    provider: actualProvider,
    model: actualModel,
    inputTokens: inputTokens,
    outputTokens: outputTokens
  }
};

return [{ json: response }];

// Format an error response when validation fails
const requestBody = $items('Webhook')[0].json.body;
const payload = requestBody.payload || {};

let errorCode = 'VALIDATION_ERROR';
let errorMessage = 'Invalid request payload.';

if (!payload.provider || payload.provider !== 'openrouter') {
  errorMessage = `Unsupported provider: "${payload.provider || 'undefined'}". Only "openrouter" is supported by this workflow.`;
} else if (!payload.model) {
  errorMessage = 'Missing required field: model. The exact model ID must be specified.';
}

const response = {
  success: false,
  requestId: requestBody.requestId || 'unknown',
  error: {
    code: errorCode,
    message: errorMessage
  }
};

return [{ json: response }];

// Format an error response when OpenRouter fails
// This catches HTTP errors, timeouts, and invalid responses
const requestBody = $items('Webhook')[0].json.body;
const errorItem = $input.first().json;

// Extract error details from the OpenRouter HTTP response
let errorMessage = 'OpenRouter request failed.';
let errorCode = 'PROVIDER_ERROR';

if (errorItem.error) {
  errorMessage = errorItem.error.message || errorMessage;
} else if (errorItem.message) {
  errorMessage = errorItem.message;
}

// Check for common OpenRouter error patterns
if (errorMessage.includes('401') || errorMessage.includes('Unauthorized')) {
  errorCode = 'AUTH_ERROR';
  errorMessage = 'OpenRouter authentication failed. Check the API key in n8n credentials.';
} else if (errorMessage.includes('404') || errorMessage.includes('not found')) {
  errorCode = 'MODEL_NOT_FOUND';
  errorMessage = `OpenRouter could not find the requested model: ${requestBody.payload.model}`;
} else if (errorMessage.includes('429') || errorMessage.includes('rate limit')) {
  errorCode = 'RATE_LIMITED';
  errorMessage = 'OpenRouter rate limit exceeded. Please try again later.';
} else if (errorMessage.includes('timeout') || errorMessage.includes('ETIMEDOUT')) {
  errorCode = 'TIMEOUT';
  errorMessage = 'OpenRouter request timed out.';
}

const response = {
  success: false,
  requestId: requestBody.requestId || 'unknown',
  error: {
    code: errorCode,
    message: errorMessage
  }
};

return [{ json: response }];
